DECLARE @PrevQStart date = DATEADD(quarter, -1, @QStart);

SELECT
  SUM(CASE WHEN OrderDate BETWEEN @QStart AND @AsOf THEN 1 ELSE 0 END) AS QTD,
  SUM(CASE WHEN OrderDate BETWEEN @PrevQStart AND DATEADD(day, @Days, @PrevQStart)
           THEN 1 ELSE 0 END) AS PrevQTD
FROM brokerage.TradeOrders;

